-- GenDB engine variant Q18-conjunct_permutation: template q18.sql, kind conjunct_permutation (generated by generate.py; frozen)
SELECT
  c_name,
  c_custkey,
  o_orderkey,
  o_orderdate,
  o_totalprice,
  SUM(l_quantity) AS sum_qty
FROM customer, orders, lineitem
WHERE
  o_orderkey = l_orderkey
  AND c_custkey = o_custkey
  AND o_orderkey IN (
    SELECT
      l_orderkey
    FROM lineitem
    GROUP BY
      l_orderkey
    HAVING
      SUM(l_quantity) > $1
  )
GROUP BY
  c_name,
  c_custkey,
  o_orderkey,
  o_orderdate,
  o_totalprice
ORDER BY
  o_totalprice DESC,
  o_orderdate
LIMIT 100
